-- PROPUESTA: NO APLICADA. Solo configuration(), sin RLS/GRANT ni cambios de usuarios.
BEGIN; SET LOCAL lock_timeout='2s'; SET LOCAL statement_timeout='30s';
DO $$ BEGIN
 IF current_database()<>'postgres' OR current_user<>'postgres' OR current_setting('dentaia.academic_activation_approval',true) IS DISTINCT FROM 'vwmdknzjyvmsdqpepykz:fase8-synthetic-v1' THEN RAISE EXCEPTION 'EXPLICIT_ACADEMIC_APPROVAL_REQUIRED'; END IF;
 IF (SELECT count(*) FROM auth.users WHERE id=ANY(ARRAY['798b53d9-9bfb-483b-8f6e-6d28403a1925','f244056c-e9bc-44e4-94d6-5b93e610429b','d3374749-74b2-4146-8c40-05a268d57af9','c7a44fd8-045b-4096-a1db-0df0b46f2969','42ce87d9-0b63-422c-9805-d25b2f681b71']::uuid[]) AND raw_app_meta_data->'dentaia_development'->>'dataset'='fase8-synthetic-v1')<>5 THEN RAISE EXCEPTION 'FIVE_SYNTHETIC_ACTORS_REQUIRED'; END IF;
 IF has_function_privilege('anon','clinical_service.configuration()','EXECUTE') OR has_function_privilege('authenticated','clinical_service.configuration()','EXECUTE') THEN RAISE EXCEPTION 'UNSAFE_CONFIGURATION_ACL';END IF;
END $$;
CREATE OR REPLACE FUNCTION clinical_service.configuration() RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $academic$
 SELECT jsonb_build_object(
 'enabled',coalesce((coalesce(nullif(current_setting('request.jwt.claim.sub',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub'))=ANY((ARRAY['798b53d9-9bfb-483b-8f6e-6d28403a1925','f244056c-e9bc-44e4-94d6-5b93e610429b','d3374749-74b2-4146-8c40-05a268d57af9','c7a44fd8-045b-4096-a1db-0df0b46f2969','42ce87d9-0b63-422c-9805-d25b2f681b71']::uuid[])::text[]),false)
 AND (SELECT count(*) FROM clinical.patient_records WHERE id=ANY(ARRAY['062e3d4f-3fb0-4c97-9157-8a3728adb044','dd730ee9-e76f-4ffc-a30e-07a8f0198f0b']::uuid[]))=2
 AND (SELECT count(*) FROM clinical.professional_accounts WHERE id=ANY(ARRAY['e4e70b50-8d74-4a93-9620-120386bab374','2f1cc39c-b184-4f6e-b7ad-eda67135c91d']::uuid[]))=2
 AND (SELECT count(*) FROM clinical.clinic_memberships WHERE id=ANY(ARRAY['6d610039-c626-43d4-9633-88a8c9366f17','f7d3bb7c-968f-4c14-a3ec-88c90b8cda68']::uuid[]) AND clinic_id=ANY(ARRAY['ed2c6a61-315f-4655-94f0-4dc454902637','27901b90-4340-45b5-acea-e655ede37c64']::uuid[]) AND professional_id=ANY(ARRAY['e4e70b50-8d74-4a93-9620-120386bab374','2f1cc39c-b184-4f6e-b7ad-eda67135c91d']::uuid[]))=2
 AND NOT EXISTS(SELECT 1 FROM clinical.clinic_memberships WHERE professional_id=ANY(ARRAY['e4e70b50-8d74-4a93-9620-120386bab374','2f1cc39c-b184-4f6e-b7ad-eda67135c91d']::uuid[]) AND NOT(id=ANY(ARRAY['6d610039-c626-43d4-9633-88a8c9366f17','f7d3bb7c-968f-4c14-a3ec-88c90b8cda68']::uuid[])))
 AND NOT EXISTS(SELECT 1 FROM clinical.clinical_encounters WHERE patient_id=ANY(ARRAY['062e3d4f-3fb0-4c97-9157-8a3728adb044','dd730ee9-e76f-4ffc-a30e-07a8f0198f0b']::uuid[]) AND (NOT(id=ANY(ARRAY['1a710e35-c54d-4728-815e-4d811d083b59','3c7206d0-1a25-4256-8b11-dc3b7f05f01f','371219cf-e677-4e8c-8029-e80ef8d19eec']::uuid[])) OR NOT(membership_id=ANY(ARRAY['6d610039-c626-43d4-9633-88a8c9366f17','f7d3bb7c-968f-4c14-a3ec-88c90b8cda68']::uuid[]))))
 AND NOT EXISTS(SELECT 1 FROM clinical.clinical_entries WHERE encounter_id=ANY(ARRAY['1a710e35-c54d-4728-815e-4d811d083b59','3c7206d0-1a25-4256-8b11-dc3b7f05f01f','371219cf-e677-4e8c-8029-e80ef8d19eec']::uuid[]) AND NOT(id=ANY(ARRAY['00c34e93-55b2-4663-aa47-f3f0cb7a66c0','2106458f-4391-44eb-b751-31687d06dc70','35f94c3a-f745-4448-b438-f0c5e426297c','59407e62-10b2-4d4c-8a5f-b4e72c11da89','abc73c27-5a02-4d1f-aa8c-49d5a052a0aa','98c933c3-ceca-4b4a-9b1b-0bebdda56013','38260ed2-906e-4e72-9d0b-c49e39afd48d','8bc08469-a947-4be5-a08a-4150402805c1','1aa57c12-c333-4cc3-9eda-da89ab2aaeb4']::uuid[])))
 AND NOT EXISTS(SELECT 1 FROM clinical.clinical_documents WHERE encounter_id=ANY(ARRAY['1a710e35-c54d-4728-815e-4d811d083b59','3c7206d0-1a25-4256-8b11-dc3b7f05f01f','371219cf-e677-4e8c-8029-e80ef8d19eec']::uuid[]) AND (NOT(id=ANY(ARRAY['97f62daf-398e-496a-95d7-7b375501446e','608ad30e-55eb-4e7d-bbf1-a2a18b554b7a','c4393275-ac8c-4020-a42d-e08ec675e037']::uuid[])) OR availability<>'unavailable'))
 AND NOT EXISTS(SELECT 1 FROM public.appointment_requests WHERE dentist_id=ANY(ARRAY['08d0c38f-2505-43ae-9c3a-2b3ccfa6b2fb','77a82d0a-909a-4833-825d-cd4d57cf2a2b']::uuid[]) AND NOT(id=ANY(ARRAY['e50e11ca-59e8-4a1f-8936-76a81dfecd9b','03271d59-1dd1-4661-8d2c-fedbbc6c5e3c','897cbad0-3f1d-491a-9a7d-b7f1d49dcc6c']::uuid[])))
 AND NOT EXISTS(SELECT 1 FROM clinical.clinical_access_grants WHERE (membership_id=ANY(ARRAY['6d610039-c626-43d4-9633-88a8c9366f17','f7d3bb7c-968f-4c14-a3ec-88c90b8cda68']::uuid[]) AND NOT(patient_id=ANY(ARRAY['062e3d4f-3fb0-4c97-9157-8a3728adb044','dd730ee9-e76f-4ffc-a30e-07a8f0198f0b']::uuid[]))) OR (patient_id=ANY(ARRAY['062e3d4f-3fb0-4c97-9157-8a3728adb044','dd730ee9-e76f-4ffc-a30e-07a8f0198f0b']::uuid[]) AND NOT(membership_id=ANY(ARRAY['6d610039-c626-43d4-9633-88a8c9366f17','f7d3bb7c-968f-4c14-a3ec-88c90b8cda68']::uuid[]))))
 AND NOT EXISTS(SELECT 1 FROM clinical.clinical_grant_resources x JOIN clinical.clinical_access_grants g ON g.id=x.grant_id WHERE g.patient_id=ANY(ARRAY['062e3d4f-3fb0-4c97-9157-8a3728adb044','dd730ee9-e76f-4ffc-a30e-07a8f0198f0b']::uuid[]) AND NOT(x.encounter_id=ANY(ARRAY['1a710e35-c54d-4728-815e-4d811d083b59','3c7206d0-1a25-4256-8b11-dc3b7f05f01f','371219cf-e677-4e8c-8029-e80ef8d19eec']::uuid[]))),
 'policyVersion','QA-NO-CLINICO-v1','purpose','academic_shared_history_qa','maxGrantSeconds',86400,'maxResources',100,'maxPage',50,'maxNested',100,
 'environment','academic_remote','dataset','fase8-synthetic-v1');
$academic$;
COMMIT;
